import { anyApi } from "convex/server";
import type { FunctionReference } from "convex/server";
import type { ProviderLimit } from "../../convex/limits";

/**
 * `convex/limits.ts` exists on disk and is frozen against
 * `convex/lib/contracts.ts`/`convex/schema.ts`, but `convex/_generated/
 * api.d.ts` (a build artifact regenerated by `npx convex dev`/`convex
 * codegen` — both talk to the deployment, out of scope for a no-deploy job)
 * does not list the `limits` module yet. Same `anyApi` workaround `src/
 * library/summaryApi.tsx` already uses for `convex/summary.ts` — this
 * resolves to the exact same function reference at runtime. Swap for
 * `api.limits.all` once codegen has run and picked up the module.
 */
export const limitsAllQuery = anyApi.limits.all as unknown as FunctionReference<
  "query",
  "public",
  Record<string, never>,
  ProviderLimit[]
>;
